mapper.select:
SELECT business_id AS id FROM coordinator_plan WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} AND message_id = #{messageId}
ORDER BY plan_version DESC

SELECT id AS database_id, business_id, plan_id, request_id, expert_id,
session_id, status, last_sequence
FROM coordinator_task WHERE tenant_id = #{tenantId} AND request_id = #{requestId}

mapper.update:
UPDATE coordinator_task SET session_id = #{sessionId}, status = 'RUNNING',
last_sequence = 0, updated_at = CURRENT_TIMESTAMP WHERE business_id = #{taskId}
AND status = 'WAITING_HUMAN'

mapper.select:
SELECT session_id FROM project_conversation_expert_session
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND conversation_id = #{conversationId} AND expert_id = #{expertId}
AND message_id <> #{currentMessageId}

mapper.update:
UPDATE project_conversation SET coordinator_session_id = #{sessionId},
coordinator_agent_id = #{agentId}
WHERE business_id = #{conversationId}
AND coordinator_session_id IS NULL

UPDATE coordinator_dispatch SET status = #{status}, last_error = #{error},
lease_owner = NULL, lease_expires_at = NULL, updated_at = CURRENT_TIMESTAMP
WHERE business_id = #{dispatchId}

mapper.select:
SELECT id AS database_id, business_id, plan_id, request_id, expert_id,
session_id, status, last_sequence
FROM coordinator_task WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} AND business_id = #{taskId}

SELECT d.business_id FROM coordinator_task t
JOIN coordinator_plan p ON p.business_id = t.plan_id
JOIN coordinator_dispatch d ON d.message_id = p.message_id
AND d.tenant_id = p.tenant_id
WHERE t.tenant_id = #{tenantId} AND t.project_id = #{projectId}
AND t.business_id = #{taskId}
